export function areAnagrams(a,b) {
  if(a.length!==b.length)return false;
  const count=new Map();for(const c of a)count.set(c,(count.get(c)||0)+1);
  for(const c of b){const n=count.get(c)||0;if(!n)return false;count.set(c,n-1);}
  return true;
}
